toolArgs.file_text:
.catalog-layout {
    display: flex;
    gap: 1.5rem;
}

.catalog-filters {
    flex: 0 0 25%;
    padding: 1rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    align-self: flex-start;
}

.catalog-filters h2 {
    margin-top: 0;
}

.filter-section {
    margin-bottom: 1.25rem;
}

.filter-section h3 {
    margin-bottom: 0.5rem;
    font-size: 0.95rem;
}

.filter-checkbox {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.35rem;
    cursor: pointer;
}

.price-inputs {
    display: flex;
    gap: 0.75rem;
}

.price-inputs label {
    display: flex;
    flex-direction: column;
    font-size: 0.85rem;
}

.price-inputs input {
    width: 90px;
    padding: 0.3rem 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.btn-apply,
.btn-clear {
    padding: 0.5rem 1rem;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-apply {
    background: #1a73e8;
    color: white;
}

.btn-apply:hover {
    background: #1557b0;
}

.btn-clear {
    background: #f1f3f4;
    color: #333;
}

.btn-clear:hover {
    background: #e0e0e0;
}

/* Main content area */
.catalog-main {
    flex: 1;
}

.catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border-radius: 6px;
}

.sort-control {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.sort-control select {
    padding: 0.35rem 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
}

.result-count {
    font-size: 0.9rem;
    color: #666;
}

/* Product grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1.25rem;
}

.product-card {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
    cursor: pointer;
    transition: box-shadow 0.2s;
}

.product-card:hover {
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.12);
}

.product-image {
    height: 160px;
    background: #f0f0f0;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 0.85rem;
    text-align: center;
    padding: 0.5rem;
}

.product-info {
    padding: 0.75rem;
}

.product-name {
    margin: 0 0 0.4rem;
    font-size: 1rem;
}

.product-price {
    margin: 0 0 0.3rem;
    font-weight: 600;
    color: #1a73e8;
}

.product-rating {
    margin: 0 0 0.4rem;
    color: #f5a623;
}

.badge-out-of-stock {
    display: inline-block;
    background: #dc3545;
    color: white;
    font-size: 0.75rem;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
    margin-bottom: 0.5rem;
}

.btn-add-to-cart {
    width: 100%;
    padding: 0.5rem;
    border: none;
    border-radius: 4px;
    background: #28a745;
    color: white;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-add-to-cart:hover:not(:disabled) {
    background: #218838;
}

.btn-add-to-cart:disabled {
    background: #ccc;
    cursor: not-allowed;
}

/* Pagination */
.catalog-pagination {
    display: flex;
    justify-content: center;
    gap: 0.4rem;
    margin-top: 1.5rem;
    padding: 1rem 0;
}

.btn-page {
    padding: 0.4rem 0.75rem;
    border: 1px solid #ddd;
    border-radius: 4px;
    background: white;
    cursor: pointer;
}

.btn-page:hover:not(:disabled) {
    background: #f0f0f0;
}

.btn-page.active {
    background: #1a73e8;
    color: white;
    border-color: #1a73e8;
}

.btn-page:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* States */
.catalog-loading,
.catalog-error,
.catalog-empty {
    text-align: center;
    padding: 3rem 1rem;
}

.catalog-error {
    color: #dc3545;
}

.catalog-error button {
    margin-top: 1rem;
    padding: 0.5rem 1rem;
    background: #1a73e8;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

